export function countOccurrences(words: string[], target: string): number {
  const needle = target.toLowerCase();
  let count = 0;
  for (let i = 0; i < words.length; i += 1) {
    const word = words[i];
    if (word.length === needle.length && word.toLowerCase() === needle) {
      count += 1;
    }
  }
  return count;
}

export function countOccurrences(words: string[], target: string): number {
  const needle = target.toLowerCase();
  let count = 0;
  for (let i = 0; i < words.length; i += 1) {
    const word = words[i];
    if (word.length !== needle.length) continue;

    let matches = true;
    for (let j = 0; j < needle.length; j += 1) {
      const code = word.charCodeAt(j);
      const lowerCode = code >= 65 && code <= 90 ? code + 32 : code;
      if (lowerCode !== needle.charCodeAt(j)) {
        matches = false;
        break;
      }
    }
    if (matches) count += 1;
  }
  return count;
}

