export function maxWindowSum(xs: number[], k: number): number | null {
  if (k <= 0) {
    throw new Error("window size must be positive");
  }
  if (k > xs.length) {
    return null;
  }
  let sum = 0;
  for (let i = 0; i < k; i++) {
    sum += xs[i];
  }
  let best = sum;
  for (let i = k; i < xs.length; i++) {
    sum += xs[i] - xs[i - k];
    if (sum > best) {
      best = sum;
    }
  }
  return best;
}

export function maxSubarraySum(xs: number[]): number {
  if (xs.length === 0) {
    throw new Error("empty input");
  }
  let best = xs[0];
  let cur = xs[0];
  for (let i = 1; i < xs.length; i++) {
    const x = xs[i];
    const sum = cur + x;
    cur = sum > x ? sum : x;
    if (cur > best) best = cur;
  }
  return best;
}

