export function sortPointsByY(
  points: { x: number; y: number }[],
): { x: number; y: number }[] {
  return points.slice().sort((a, b) => (a.y < b.y ? -1 : a.y > b.y ? 1 : 0));
}

export function spread(
  xs: number[],
): { count: number; min: number; max: number; range: number } | null {
  const n = xs.length;
  if (n === 0) {
    return null;
  }

  let lo = xs[0];
  let hi = xs[0];
  for (let i = 1; i < n; i++) {
    const x = xs[i];
    if (x < lo) lo = x;
    else if (x > hi) hi = x;
  }

  return { count: n, min: lo, max: hi, range: hi - lo };
}

export function spread(
  xs: number[],
): { count: number; min: number; max: number; range: number } | null {
  const n = xs.length;
  if (n === 0) return null;

  let lo = xs[0];
  let hi = xs[0];
  for (let i = 1; i < n; i++) {
    const x = xs[i];
    lo = Math.min(lo, x);
    hi = Math.max(hi, x);
  }
  return { count: n, min: lo, max: hi, range: hi - lo };
}

