export function clamp(value: number, lo: number, hi: number): number {
  if (lo > hi) {
    throw new Error("clamp: lower bound exceeds upper bound");
  }
  return value < lo ? lo : value > hi ? hi : value;
}

export function twoSum(xs: number[], target: number): [number, number] | null {
  const n = xs.length;
  for (let i = 0; i < n - 1; i++) {
    const x = xs[i];
    const end = n - i;
    for (let offset = 1; offset < end; offset++) {
      const j = i + offset;
      if (x + xs[j] === target) {
        return [i, j];
      }
    }
  }
  return null;
}

export function factorial(n: number): number {
  if (n < 0) {
    throw new Error("factorial of a negative number");
  }
  let result = 1;
  let i = 2;
  while (i <= n) {
    result *= i;
    i++;
  }
  return result;
}

