    throw new Error("factorial of a negative number");
  }
  if (n < 2) return 1;
  if (n === 2) return 2;
  if (n === 3) return 6;
  let result = 6;
  for (let i = 4; i <= n; i++) {
    result *= i;
  }
  return result;
}

export function collatzSteps(n: number, maxSteps: number): number {
  if (n < 1) {
    throw new Error("n must be a positive integer");
  }
  if (n === 1) {
    return 0;
  }

  let x = n;
  let step = 0;
  while (step < maxSteps) {
    const half = Math.floor(x / 2);
    if (x === half * 2) {
      x = half;
    } else {
      x = 3 * x + 1;
    }
    step++;
    if (x === 1) {
      return step;
    }
  }
  throw new Error("step limit exceeded");
}

export function digitSum(value: number): number {
  let n = Math.abs(value);
  let sum = 0;

  // Process pairs of decimal digits; each step removes two digits.
  while (n >= 100) {
    const pair = n % 100;
    sum += (pair % 10) + Math.floor(pair / 10);
    n = Math.floor(n / 100);
  }

  if (n > 0) {
    sum += (n % 10) + Math.floor(n / 10);
  }

  return sum;
}

export function floorDivMod(a: number, b: number): [number, number] {
  if (b === 0) {
    throw new Error("division by zero");
  }
  const r0 = a % b;
  const r = r0 !== 0 && ((r0 < 0) !== (b < 0)) ? r0 + b : r0;
  const q = Math.floor(a / b);
  return [q, r];
}

