export function intPow(base: number, exponent: number): number {
  if (exponent < 0) {
    throw new Error("negative exponent");
  }
  let result = 1;
  let b = base;
  let e = exponent;
  while (e > 0) {
    if (e % 2 === 1) {
      result = result * b;
    }
    e = Math.floor(e / 2);
    if (e > 0) {
      b = b * b;
    }
  }
  return result;
}

export function reverseDigits(n: number, acc: number): number {
  if (n < 0) {
    throw new Error("reverseDigits expects a non-negative integer");
  }
  while (n > 0) {
    acc = acc * 10 + (n % 10);
    n = Math.floor(n / 10);
  }
  return acc;
}

