export function toBinary(n: number): string {
  if (n < 0) {
    throw new Error("toBinary expects a non-negative integer");
  }
  if (n < 2) {
    return n === 0 ? "0" : "1";
  }

  let value = n;
  let result = "";
  while (value >= 2) {
    result = (value % 2 === 0 ? "0" : "1") + result;
    value = Math.floor(value / 2);
  }
  return (value === 0 ? "0" : "1") + result;
}

