export function reverseString(s: string): string {
  let out = "";
  let i = s.length;
  while (i >= 4) {
    out += s.charAt(i - 1) + s.charAt(i - 2) + s.charAt(i - 3) + s.charAt(i - 4);
    i -= 4;
  }
  while (i > 0) {
    out += s.charAt(i - 1);
    i--;
  }
  return out;
}

export function longestRun(s: string): { char: string; length: number } | null {
  const n = s.length;
  if (n === 0) {
    return null;
  }

  let bestChar = s.charAt(0);
  let bestLen = 0;
  let runChar = bestChar;
  let runLen = 0;

  for (let i = 0; i < n; i++) {
    const c = s.charAt(i);
    if (c === runChar) {
      runLen++;
    } else {
      if (runLen > bestLen || (runLen === bestLen && runChar < bestChar)) {
        bestChar = runChar;
        bestLen = runLen;
      }
      runChar = c;
      runLen = 1;
    }
  }

  if (runLen > bestLen || (runLen === bestLen && runChar < bestChar)) {
    bestChar = runChar;
    bestLen = runLen;
  }

  return { char: bestChar, length: bestLen };
}

