export function trimControl(s: string): string {
  const n = s.length;
  let left = 0;
  let right = n;

  while (left < right && s.charCodeAt(left) <= 32) left++;
  while (left < right && s.charCodeAt(right - 1) <= 32) right--;

  return s.slice(left, right);
}

export function trimControl(s: string): string {
  let start = 0;
  let end = s.length;
  while (start < end && s.charCodeAt(start) <= 32) start++;
  while (end > start && s.charCodeAt(end - 1) <= 32) end--;
  return s.slice(start, end);
}
